function Item_Custom() {
    var itemTypes = Item_GetTypeManager();

    #macro ITEM_DICE "dice"
    itemTypes.Register(ITEM_DICE, new CustomItem_Dice());

    var inventories = Item_GetInventoryManager();
    inventories.Register("items", new Inventory(itemTypes, 8));
}

function CustomItem_Dice() : ItemType() constructor {
    _price_buy = 4;
    _price_sell = 0;

    function GetName() {
        return choose("Dice", "Dice?", "Dice!");
    }

    function OnUse(inventory, index) {
        var number = irandom_range(1, 6);
        Dialog_Add($"* You rolled the dice.&* It's a {number}!");

        if (number == 1) {
            inventory.Add(ITEM_DICE);   // 再来一个
        } else if (number == 6) {
            inventory.Remove(index);    // 自己消失
        }
        Dialog_Start();
    }

    function OnInfo(inventory, index) {
        Dialog_Add("* 一个六面骰子。");
        Dialog_Start();
    }
}

